*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{
  height:100%;
  width:100%;
  font-family:-apple-system,BlinkMacSystemFont,'SF Pro Text','SF Pro Display','Helvetica Neue',Helvetica,Arial,sans-serif;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
  background:var(--bg);
  color:var(--fg);
}
body{overflow:hidden}
button,input,textarea,select{font:inherit}
button{background:none;border:none}
a{color:inherit}
:focus-visible{outline:2px solid var(--blue-l);outline-offset:2px}
.sr-only{
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  margin:-1px;
  overflow:hidden;
  clip-path:inset(50%);
  white-space:nowrap;
  border:0;
}
#bg{position:fixed;inset:0;z-index:0;overflow:hidden;pointer-events:none}
.orb{position:absolute;border-radius:50%;filter:blur(110px);animation:drift var(--d,24s) ease-in-out infinite alternate}
.o1{width:480px;height:480px;top:-100px;right:-80px;background:radial-gradient(circle,rgba(0,113,227,.12) 0%,transparent 70%);--d:22s}
.o2{width:360px;height:360px;bottom:12%;left:-100px;background:radial-gradient(circle,rgba(70,70,190,.08) 0%,transparent 70%);--d:29s;animation-direction:alternate-reverse}
.o3{width:280px;height:280px;bottom:0;right:8%;background:radial-gradient(circle,rgba(0,70,150,.06) 0%,transparent 70%);--d:20s}
@keyframes drift{
  0%{transform:translate(0,0) scale(1)}
  33%{transform:translate(16px,-20px) scale(1.03)}
  66%{transform:translate(-10px,14px) scale(.97)}
  100%{transform:translate(20px,8px) scale(1.02)}
}
#app{display:flex;flex-direction:column;height:100dvh;width:100%;position:relative;overflow:hidden}
#sidebar{
  position:fixed;
  inset:0;
  z-index:310;
  padding-top:var(--sat);
  background:var(--surface);
  backdrop-filter:blur(40px) saturate(180%) brightness(95%);
  -webkit-backdrop-filter:blur(40px) saturate(180%) brightness(95%);
  display:flex;
  flex-direction:column;
  transform:translateX(-100%);
  transition:transform 320ms cubic-bezier(.2,.9,.2,1);
  pointer-events:none;
}
#sidebar[aria-hidden="false"]{pointer-events:auto}
#sidebar.open{transform:translateX(0)}
#sidebar.dragging{transition:none}
.sb-hdr{
  height:52px;
  display:flex;
  align-items:center;
  padding:0 12px;
  border-bottom:.5px solid var(--sep);
  flex-shrink:0;
  gap:6px;
}
.sb-title{flex:1;text-align:center;font-size:.9375rem;font-weight:600;letter-spacing:-.01875rem;color:var(--fg)}
.sb-close{
  width:28px;
  height:28px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--input-bg);
  color:var(--fg3);
  cursor:pointer;
  transition:transform .18s cubic-bezier(.2,1,.3,1),opacity .12s,background .12s,color .12s;
}
.sb-close:active{transform:scale(.88);opacity:.7}
.sb-close svg{width:13px;height:13px;fill:currentColor}
#sb-search-bar{
  flex-shrink:0;
  overflow:hidden;
  height:0;
  visibility:hidden;
  transition:height .24s ease,visibility 0s linear .24s;
}
#sb-search-bar.open{
  height:54px;
  visibility:visible;
  transition:height .24s ease;
}
.sb-si{
  display:flex;
  align-items:center;
  gap:8px;
  margin:8px 14px 6px;
  background:var(--input-bg);
  border-radius:13px;
  border:.5px solid var(--input-border);
  padding:0 12px;
  height:38px;
}
.sb-si svg{width:15px;height:15px;fill:var(--fg3);flex-shrink:0}
#sb-q{
  flex:1;
  background:transparent;
  border:none;
  outline:none;
  font-size:.9375rem;
  color:var(--fg);
  padding:0;
  min-width:0;
}
#sb-q::placeholder{color:var(--fg3)}
#sb-q-cancel{
  background:none;
  cursor:pointer;
  font-size:.875rem;
  font-weight:500;
  color:var(--blue-l);
  padding:0 0 0 8px;
  white-space:nowrap;
  transition:opacity .2s,width .24s ease;
  overflow:hidden;
  width:0;
  opacity:0;
  flex-shrink:0;
  pointer-events:none;
}
#sb-search-bar.open #sb-q-cancel{
  width:52px;
  opacity:1;
  pointer-events:auto;
}
.sb-body{
  flex:1;
  overflow-y:auto;
  overflow-x:hidden;
  -webkit-overflow-scrolling:touch;
  overscroll-behavior:contain;
  scrollbar-width:none;
  padding:12px;
}
.sb-body::-webkit-scrollbar{display:none}
.sb-pull-hint{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:5px;
  padding:6px 0 0;
  font-size:.6875rem;
  color:var(--fg3);
  pointer-events:none;
  opacity:0;
  transition:opacity .2s;
}
.sb-pull-hint svg{width:12px;height:12px;fill:var(--fg3)}
#sidebar.pull-hinting .sb-pull-hint{opacity:1}
.sb-new{
  display:flex;
  align-items:center;
  gap:10px;
  padding:11px 13px;
  border-radius:12px;
  margin-bottom:10px;
  width:100%;
  cursor:pointer;
  background:rgba(0,113,227,.12);
  border:.5px solid rgba(0,113,227,.2);
  font-size:.84375rem;
  font-weight:500;
  color:var(--blue-l);
  transition:transform .22s cubic-bezier(.2,1,.3,1),background .14s;
  text-align:left;
}
.sb-new:active{background:rgba(0,113,227,.2);transform:scale(.97)}
.sb-new svg{width:15px;height:15px;fill:currentColor;flex-shrink:0}
@media (prefers-color-scheme:light){.sb-new{background:rgba(0,113,227,.08)}}
.sb-sec{font-size:.6875rem;font-weight:600;color:var(--fg3);letter-spacing:.03125rem;text-transform:uppercase;padding:2px 3px 8px;margin-top:4px}
.hcard{
  display:flex;
  align-items:flex-start;
  gap:10px;
  padding:11px 12px;
  border-radius:12px;
  cursor:pointer;
  margin-bottom:6px;
  background:transparent;
  border:.5px solid transparent;
  transition:transform .22s cubic-bezier(.2,1,.3,1),background .14s,border-color .14s;
}
.hcard:hover{background:var(--input-bg);border-color:var(--border-s)}
.hcard:active{transform:scale(.97);background:var(--input-bg)}
.hcard.active{background:rgba(0,113,227,.1);border-color:rgba(0,113,227,.18)}
@media (prefers-color-scheme:light){.hcard.active{background:rgba(0,113,227,.08)}}
.hcard-body{flex:1;min-width:0}
.hcard-pre{font-size:.8125rem;font-weight:500;color:var(--fg);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:-.009375rem}
.hcard-pre mark{background:rgba(0,113,227,.22);color:var(--blue-l);border-radius:3px;padding:0 1px}
.hcard.active .hcard-pre{color:var(--blue-l)}
.hcard-meta{font-size:.6875rem;color:var(--fg3);margin-top:2px}
.hcard-del{
  width:24px;
  height:24px;
  border-radius:6px;
  flex-shrink:0;
  display:flex;
  align-items:center;
  justify-content:center;
  background:transparent;
  color:var(--fg3);
  cursor:pointer;
  opacity:0;
  pointer-events:none;
  transition:opacity .13s,transform .2s cubic-bezier(.2,1,.3,1),background .12s,color .12s;
}
.hcard:hover .hcard-del,
.hcard:focus-within .hcard-del{opacity:1;pointer-events:auto}
.hcard-del:active{background:rgba(255,59,48,.15);color:rgba(255,59,48,.8);transform:scale(.85)}
.hcard-del svg{width:13px;height:13px;fill:currentColor}
.h-empty{display:flex;flex-direction:column;align-items:center;gap:9px;padding:48px 16px;text-align:center}
.h-empty svg{width:28px;height:28px;fill:var(--fg3);opacity:.45}
.h-empty p{font-size:.8125rem;color:var(--fg3);line-height:1.5}
#content{flex:1;overflow:hidden;position:relative;z-index:1;touch-action:pan-y}
#scroll-area{
  position:absolute;
  top:var(--sat);
  right:0;
  bottom:0;
  left:0;
  overflow-y:auto;
  overflow-x:hidden;
  -webkit-overflow-scrolling:touch;
  overscroll-behavior-y:contain;
  touch-action:pan-y;
  scrollbar-width:none;
  padding:12px 0 84px;
  scroll-padding:20px 0;
}
#scroll-area::-webkit-scrollbar{display:none}
#scroll-area::after{
  content:'';
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(transparent,rgba(0,113,227,.14));
  opacity:0;
  transition:opacity .25s cubic-bezier(.23,1,.32,1);
  z-index:1;
}
#scroll-area:active::after,#scroll-area.scrolling::after{opacity:.6}
#msg-list{display:flex;flex-direction:column;padding:0 14px;min-height:100%}
.msg-group{
  display:flex;
  flex-direction:column;
  margin-bottom:14px;
  animation:bubbleSpring .45s cubic-bezier(.34,1.2,.64,1) both;
}
.msg-group.u{align-items:flex-end}
.msg-group.a{align-items:flex-start}
@keyframes bubbleSpring{
  from{transform:translateY(14px) scale(.93);opacity:0}
  to{transform:none;opacity:1}
}
.bubble{
  max-width:min(76vw,344px);
  padding:10px 14px;
  font-size:.9375rem;
  line-height:1.5;
  letter-spacing:-.01125rem;
  word-break:break-word;
  border-radius:18px;
}
.u .bubble{
  background:var(--user-bg);
  color:#fff;
  border-bottom-right-radius:4px;
  box-shadow:0 1px 8px rgba(0,113,227,.25),0 0 0 .5px rgba(0,113,227,.12);
  animation:bubbleIn .32s cubic-bezier(.34,1.15,.64,1);
}
@keyframes bubbleIn{
  from{opacity:0;transform:translateY(12px) scale(.93)}
  to{opacity:1;transform:none}
}
@keyframes aiBubbleIn{
  from{opacity:0;transform:translateX(-8px) scale(.97)}
  to{opacity:1;transform:none}
}
.ai-bubble{
  max-width:min(88vw,440px);
  padding:12px 15px;
  font-size:.9375rem;
  line-height:1.55;
  letter-spacing:-.009375rem;
  word-break:break-word;
  border-radius:18px;
  border-bottom-left-radius:4px;
  background:var(--ai-bg);
  color:var(--ai-fg);
  backdrop-filter:blur(24px) saturate(140%);
  -webkit-backdrop-filter:blur(24px) saturate(140%);
  border:.5px solid var(--border);
  box-shadow:0 1px 3px rgba(0,0,0,.16);
  animation:aiBubbleIn .36s cubic-bezier(.34,1.08,.64,1);
}
.img-in-msg{border-radius:14px;overflow:hidden;max-width:220px;max-height:185px;object-fit:cover;display:block;margin-bottom:6px;box-shadow:0 1px 6px rgba(0,0,0,.2)}
.img-badge{
  display:inline-flex;
  align-items:center;
  gap:6px;
  margin-bottom:6px;
  padding:6px 10px;
  border-radius:10px;
  background:var(--input-bg);
  color:var(--fg2);
  font-size:.75rem;
  border:.5px solid var(--border-s);
}
.rc-wrap{
  max-width:min(88vw,440px);
  border-radius:14px;
  overflow:hidden;
  margin-bottom:6px;
  border:.5px solid var(--border-s);
  background:var(--rc-bg);
  backdrop-filter:blur(20px) saturate(130%);
  -webkit-backdrop-filter:blur(20px) saturate(130%);
}
.rc-head{display:flex;align-items:center;justify-content:space-between;padding:8px 13px;cursor:pointer;user-select:none;gap:8px}
.rc-label{font-size:.6875rem;font-weight:500;letter-spacing:.00625rem;color:var(--fg3)}
.rc-status{display:flex;align-items:center;gap:5px}
.rc-dot{width:5px;height:5px;border-radius:50%;background:var(--fg3);animation:pulse 1.8s ease-in-out infinite}
.rc-dot.done{animation:none;background:rgba(52,199,89,.55)}
@keyframes pulse{
  0%,100%{opacity:.25}
  50%{opacity:.85}
}
.rc-dur{font-size:.65625rem;color:var(--fg3)}
.rc-chv{font-size:.625rem;color:var(--fg3);transition:transform .22s cubic-bezier(.4,0,.2,1)}
.rc-chv.open{transform:rotate(180deg)}
.rc-body{overflow:hidden;max-height:0;transition:max-height .36s cubic-bezier(.32,1.08,.5,1)}
.rc-body.open{max-height:520px;overflow-y:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.rc-body.open::-webkit-scrollbar{display:none}
.rc-text{font-size:.75rem;line-height:1.6;color:var(--fg3);padding:0 13px 11px;white-space:pre-wrap;word-break:break-word;font-style:italic}
.rc-tools{padding:0 10px 10px;display:flex;flex-direction:column;gap:5px}
.rc-tools:empty{display:none}
.rc-tools .srch-wrap{max-width:100%;margin-bottom:0}
.rc-step{font-size:.65625rem;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.7;margin-top:1px;font-style:italic;max-width:200px}
.rc-tool-count{font-size:.625rem;color:var(--fg3);opacity:.7;margin-left:4px}
.srch-wrap{max-width:min(88vw,440px);margin-bottom:6px}
.srch-bar{
  display:flex;
  align-items:center;
  gap:8px;
  padding:8px 12px;
  background:rgba(0,113,227,.08);
  border:.5px solid rgba(0,113,227,.18);
  border-radius:12px;
}
.srch-bar.done{background:rgba(52,199,89,.06);border-color:rgba(52,199,89,.18)}
.srch-ico{width:13px;height:13px;flex-shrink:0;animation:spin 1s linear infinite}
.srch-ico path{fill:var(--blue-l)}
.srch-bar.done .srch-ico{animation:none}
.srch-bar.done .srch-ico path{fill:rgba(52,199,89,.8)}
@keyframes spin{to{transform:rotate(360deg)}}
.srch-q{font-size:.75rem;color:var(--blue-l);font-weight:500;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.srch-bar.done .srch-q{color:rgba(52,199,89,.8)}
.srch-count{font-size:.65625rem;color:var(--fg3);flex-shrink:0}
.src-chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:5px}
.src-chip{
  display:inline-flex;
  align-items:center;
  gap:5px;
  padding:3px 9px;
  background:var(--input-bg);
  border:.5px solid var(--border-s);
  border-radius:20px;
  text-decoration:none;
  font-size:.6875rem;
  color:var(--fg2);
  transition:transform .22s cubic-bezier(.2,1,.3,1),background .13s,color .13s;
  max-width:150px;
  min-width:0;
}
.src-chip:hover{background:var(--surface-hi);color:var(--fg)}
.src-chip:active{transform:scale(.95)}
.src-chip img{width:12px;height:12px;border-radius:2px;flex-shrink:0;object-fit:cover}
.src-chip span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.t-row{
  display:flex;
  gap:3px;
  margin-top:4px;
  padding:0 2px;
  opacity:0;
  pointer-events:none;
  transition:opacity .16s;
}
.msg-group:hover .t-row,
.msg-group:focus-within .t-row{opacity:1;pointer-events:auto}
@media (pointer:coarse){
  .t-row{opacity:1;pointer-events:auto}
  .hcard-del{opacity:1;pointer-events:auto}
}
.tact{border:none;border-radius:7px;padding:3px 9px;font-size:.65625rem;color:var(--fg3);background:var(--input-bg);cursor:pointer;font-family:inherit;transition:transform .2s cubic-bezier(.2,1,.3,1),color .12s}
.tact:active{color:var(--fg2);transform:scale(.92)}
.btime{font-size:.625rem;color:var(--fg3);margin-top:4px;padding:0 3px}
.md{color:var(--ai-fg)}
.md h1{font-size:1.09375rem;font-weight:700;letter-spacing:-.025rem;margin:9px 0 5px}
.md h2{font-size:.96875rem;font-weight:600;letter-spacing:-.01875rem;margin:8px 0 4px}
.md h3{font-size:.875rem;font-weight:600;margin:7px 0 3px}
.md strong{font-weight:600}
.md em{font-style:italic;opacity:.85}
.md a{color:var(--blue-l);text-decoration:none}
.md a:hover{text-decoration:underline}
.md ul{padding:3px 0 3px 12px;margin:3px 0;list-style:none}
.md ul li{position:relative;padding:1px 0 1px 12px}
.md ul li::before{content:'·';position:absolute;left:0;color:var(--fg3);font-size:.875rem;line-height:1.4}
.md ol{padding:3px 0 3px 18px;margin:3px 0}
.md ol li{padding:1px 0}
.md p{margin:4px 0}
.md hr{border:none;border-top:.5px solid var(--sep);margin:8px 0}
.ic{
  display:inline;
  background:rgba(255,255,255,.09);
  border-radius:4px;
  padding:1px 5px;
  font-size:.78125rem;
  font-family:'SF Mono',Consolas,'Liberation Mono',Menlo,Monaco,'Courier New',monospace;
  letter-spacing:.003125rem;
}
@media (prefers-color-scheme:light){.ic{background:rgba(0,0,0,.07)}}
.cb{border-radius:12px;overflow:hidden;margin:7px 0;box-shadow:0 3px 14px rgba(0,0,0,.2)}
.cb-hdr{display:flex;align-items:center;justify-content:space-between;padding:7px 12px;background:var(--code-header-bg);border-bottom:.5px solid var(--border)}
.cb-lang{font-size:.65625rem;font-weight:500;color:var(--fg3);letter-spacing:.03125rem;text-transform:uppercase;font-family:'SF Mono',Consolas,'Liberation Mono',Menlo,Monaco,'Courier New',monospace}
.cb-copy{background:var(--input-bg);border-radius:6px;padding:2px 9px;font-size:.65625rem;color:var(--fg2);cursor:pointer;font-family:inherit;transition:all .12s}
.cb-copy:active{background:var(--surface-hi)}
.cb pre{margin:0}
.cb pre code{
  font-family:'SF Mono',Consolas,'Liberation Mono',Menlo,Monaco,'Courier New',monospace;
  font-size:.75rem;
  line-height:1.65;
  padding:10px 13px;
  display:block;
  overflow-x:auto;
  background:var(--code-bg);
}
.typing{
  display:flex;
  gap:4.5px;
  align-items:center;
  padding:11px 14px;
  border-radius:18px;
