<script>
(function(){
  'use strict';

  const SK = 'cs_v5';
  const HK = 'ch_v5';
  const DK = 'cgd_v2';
  const MAX_IMGS = 4;
  const MAX_TEXT_FILE_BYTES = 1024 * 1024;
  const MAX_TOTAL_TEXT_FILE_BYTES = 2 * 1024 * 1024;
  const TEXT_EXTS = new Set([
    'txt','md','markdown','json','csv','tsv','xml','yaml','yml','js','mjs','cjs','ts','tsx','jsx',
    'css','scss','sass','less','html','htm','svg','py','java','kt','kts','go','rs','c','h','cpp',
    'hpp','cc','hh','cs','php','rb','swift','sql','sh','bash','zsh','fish','ini','cfg','conf','toml','env'
  ]);

  const el = id => document.getElementById(id);
  const sa = el('scroll-area');
  const ml = el('msg-list');
  const ta = el('ta');
  const sbtn = el('sbtn');
  const sico = el('sico');
  const stb = el('stb');
  const istrip = el('img-strip');
  const fstrip = el('file-strip');
  const sidebar = el('sidebar');
  const sbQ = el('sb-q');
  const sbSearchBar = el('sb-search-bar');
  const searchStatus = el('search-status');
  const fg = el('fg');

  if (!sa || !ml || !ta || !sbtn || !sico || !stb || !istrip || !fstrip || !sidebar || !sbQ || !sbSearchBar || !fg) {
    return;
  }

  let sid = null;
  let msgs = [];
  let hmeta = [];
  let deletedGroups = {};
  let imgs = [];
  let textAtts = [];
  let streaming = false;
  let ctrl = null;
  let retryT = null;
  let sbOpen = false;
  let agentMode = false;

  function escHtml(value){
    return String(value ?? '')
      .replace(/&/g,'&amp;')
      .replace(/</g,'&lt;')
      .replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;')
      .replace(/'/g,'&#39;');
  }

  function normalizeWhitespace(value){
    return String(value ?? '').replace(/\s+/g,' ').trim();
  }

  function safeSliceText(value,maxChars=280){
    return Array.from(String(value ?? '')).slice(0,maxChars).join('');
  }

  function ftime(ts = Date.now()){
    return new Date(ts).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});
  }

  function sanitizeHref(rawHref){
    const value = String(rawHref ?? '').trim();
    if (!value) return '#';
    if (/^(?:https?:| return escHtml(value);
    return '#';
  }

  function applyInlineMdSafe(text){
    const parts = [];
    let src = String(text ?? '');
    src = src.replace(/`([^`\n]+)`/g, (_, code) => {
      parts.push('<span class=\"ic\">' + escHtml(code) + '</span>');
      return '\u001EINLINE' + (parts.length - 1) + '\u001E';
    });
    src = src.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, label, href) => {
      parts.push('' + escHtml(label) + '');
      return '\u001ELINK' + (parts.length - 1) + '\u001E';
    });
    src = escHtml(src);
    src = src.replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>');
    src = src.replace(/__([\s\S]+?)__/g, '<strong>$1</strong>');
    src = src.replace(/(^|[^\*])\*([^\*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
    src = src.replace(/(^|[^_])_([^_\n]+)_(?!_)/g, '$1<em>$2</em>');
    src = src.replace(/\u001E(?:INLINE|LINK)(\d+)\u001E/g, (_, i) => parts[Number(i)] || '');
    return src;
  }

  function renderTable(raw){
    const lines = String(raw ?? '').split('\n').map(line => line.trim()).filter(Boolean);
    if (lines.length < 2) return '<p>' + applyInlineMdSafe(raw) + '</p>';
    const rows = lines.map(line => {
      const trimmed = line.replace(/^\||\|$/g,'');
      return trimmed.split('|').map(cell => cell.trim());
    });
    if (rows.length < 2) return '<p>' + applyInlineMdSafe(raw) + '</p>';
    const header = rows[0];
    const separator = rows[1];
    const sepOk = separator.every(cell => /^:?-{3,}:?$/.test(cell));
    if (!sepOk) return '<p>' + applyInlineMdSafe(raw) + '</p>';
    const body = rows.slice(2);
    let html = '<table><thead><tr>';
    html += header.map(cell => '<th>' + applyInlineMdSafe(cell) + '</th>').join('');
    html += '</tr></thead>';
    if (body.length) {
      html += '<tbody>';
      html += body.map(row => '<tr>' + row.map(cell => '<td>' + applyInlineMdSafe(cell) + '</td>').join('') + '</tr>').join('');
      html += '</tbody>';
    }
    html += '</table>';
    return html;
  }

  function md(input){
    let s = String(input ?? '').replace(/\r\n?/g,'\n');
    const codeBlocks = [];
    s = s.replace(/```([^\n`]*)\n([\s\S]*?)```/g, (_, lang, code) => {
      const language = String(lang || '').trim();
      const escaped = escHtml(code.replace(/\n$/,''));
      const cls = language ? 'language-' + language.replace(/[^\w-]/g,'') : '';
      const item = '<div class=\"cb\"><div class=\"cb-hdr\"><span class=\"cb-lang\">' + escHtml(language || 'text') + '</span><button type=\"button\" class=\"cb-copy\" data-copy-code>Kód másolása</button></div><pre><code class=\"' + escHtml(cls) + '\">' + escaped + '</code></pre></div>';
      codeBlocks.push(item);
      return '\u001FCB' + (codeBlocks.length - 1) + '\u001F';
    });

    const tableBlocks = [];
    s = s.replace(/((?:^\|.*\|\s*$\n?){2,})/gm, match => {
      const html = renderTable(match.trim());
      tableBlocks.push(html);
      return '\u001FTB' + (tableBlocks.length - 1) + '\u001F';
    });

    const blocks = s.split(/\n{2,}/);
    const out = [];

    for (const block of blocks) {
      const trimmed = block.trim();
      if (!trimmed) continue;
      if (/^\u001FCB\d+\u001F$/.test(trimmed) || /^\u001FTB\d+\u001F$/.test(trimmed)) {
        out.push(trimmed);
        continue;
      }
      if (/^#{1,3}\s+/.test(trimmed)) {
        const m = trimmed.match(/^(#{1,3})\s+([\s\S]+)$/);
        const level = Math.min(3, m[1].length);
        out.push('<h' + level + '>' + applyInlineMdSafe(m[2]) + '</h' + level + '>');
        continue;
      }
      if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
        out.push('<hr>');
        continue;
      }
      const lines = trimmed.split('\n');
      if (lines.every(line => /^\s*[-*+]\s+/.test(line))) {
        const items = lines.map(line => line.replace(/^\s*[-*+]\s+/,''));
        out.push('<ul>' + items.map(item => '<li>' + applyInlineMdSafe(item) + '</li>').join('') + '</ul>');
        continue;
      }
      if (lines.every(line => /^\s*\d+\.\s+/.test(line))) {
        const items = lines.map(line => line.replace(/^\s*\d+\.\s+/,''));
        out.push('<ol>' + items.map(item => '<li>' + applyInlineMdSafe(item) + '</li>').join('') + '</ol>');
        continue;
      }
      out.push('<p>' + applyInlineMdSafe(trimmed).replace(/\n/g,'<br>') + '</p>');
    }

    let html = out.join('');
    html = html.replace(/\u001FCB(\d+)\u001F/g, (_, i) => codeBlocks[Number(i)] || '');
    html = html.replace(/\u001FTB(\d+)\u001F/g, (_, i) => tableBlocks[Number(i)] || '');
    return html;
  }

  function toast(msg,type='inf',ms=3000){
    const wrap = el('toasts');
    if (!wrap) return;
    const icons = {
      err:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2 1 21h22L12 2zm1 16h-2v-2h2zm0-4h-2v-4h2z\"/></svg>',
      ok:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 16.17 4.83 12 3.41 13.41 9 19l12-12-1.41-1.41z\"/></svg>',
      inf:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M11 17h2v-6h-2zm0-8h2V7h-2zm1 13C6.48 22 2 17.52 2 12S6.48 2 12 2s10 4.48 10 10-4.48 10-10 10z\"/></svg>'
    };
    const t = document.createElement('div');
    t.className = 'toast';
    t.innerHTML = (icons[type] || icons.inf) + '<span>' + escHtml(msg) + '</span>';
    wrap.appendChild(t);
    window.setTimeout(() => {
      t.remove();
    }, ms);
  }

  async function cptext(text){
    const value = String(text ?? '');
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(value);
        toast('Másolva','ok',1600);
        return true;
      }
    } catch (_) {}
    const node = document.createElement('textarea');
    node.value = value;
    node.setAttribute('readonly','');
    node.style.position = 'fixed';
    node.style.left = '-9999px';
    node.style.top = '0';
    document.body.appendChild(node);
    node.select();
    let ok = false;
    try {
      ok = document.execCommand('copy');
    } catch (_) {
      ok = false;
    }
    document.body.removeChild(node);
    toast(ok ? 'Másolva' : 'Sikertelen', ok ? 'ok' : 'err', 1600);
    return ok;
  }

  function buildDownloadName(name,fallback='file.txt'){
    const raw = String(name || fallback).trim() || fallback;
    return raw.replace(/[\\/:*?"<>|]+/g,'_');
  }

  window.buildDownloadName = buildDownloadName;

  function setIBH(){
    const wrap = el('ib-wrap');
    if (!wrap || !stb) return;
    const h = wrap.offsetHeight || 0;
    sa.style.paddingBottom = (h + 18) + 'px';
    stb.style.bottom = (h + 14) + 'px';
  }

  function nearBot(){
    return sa.scrollHeight - (sa.scrollTop + sa.clientHeight) < 80;
  }

  function goBot(smooth=false){
    sa.scrollTo({ top: sa.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
