  function readFileAsText(file){
    return new Promise((resolve,reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result ?? ''));
      reader.onerror = () => reject(new Error('Nem sikerült beolvasni a fájlt'));
      reader.readAsText(file);
    });
  }

  function readFileAsDataUrl(file){
    return new Promise((resolve,reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(String(reader.result ?? ''));
      reader.onerror = () => reject(new Error('Nem sikerült beolvasni a képet'));
      reader.readAsDataURL(file);
    });
  }

  async function handleFiles(fileList){
    const files = Array.from(fileList || []);
    if (!files.length) return;

    let totalTextBytes = textAtts.reduce((sum, item) => sum + (item.size || 0), 0);

    for (const file of files) {
      const type = String(file.type || '').toLowerCase();
      const name = String(file.name || 'file');
      const lower = name.toLowerCase();
      const ext = lower.includes('.') ? lower.split('.').pop() || '' : '';

      if (type.startsWith('image/')) {
        if (imgs.length >= MAX_IMGS) {
          toast('Legfeljebb 4 kép csatolható','err');
          continue;
        }
        try {
          const dataUrl = await readFileAsDataUrl(file);
          imgs.push(dataUrl);
        } catch (e) {
          toast(e.message || 'A kép beolvasása sikertelen','err');
        }
        continue;
      }

      const isText = type.startsWith('text/') || TEXT_EXTS.has(ext);
      if (!isText) {
        toast('Nem támogatott fájltípus: ' + name,'err');
        continue;
      }
      if (file.size > MAX_TEXT_FILE_BYTES) {
        toast('A fájl túl nagy: ' + name,'err');
        continue;
      }
      if (totalTextBytes + file.size > MAX_TOTAL_TEXT_FILE_BYTES) {
        toast('Az összes szöveges csatolmány túl nagy lenne','err');
        break;
      }
      try {
        const content = await readFileAsText(file);
        textAtts.push({ name, content, size: file.size, type: type || 'text/plain' });
        totalTextBytes += file.size;
      } catch (e) {
        toast(e.message || 'A fájl beolvasása sikertelen','err');
      }
    }

    renderImgStrip();
    renderFileStrip();
    updateSendBtn();
    setIBH();
  }

  function dataUrlToImgPayload(dataUrl){
    const match = String(dataUrl || '').match(/^data:([^;]+);base64,(.+)$/);
    if (!match) return null;
    return { mime: match[1], data: match[2] };
  }

