  async function restoreSid(id){
    if (!id) return;
    try {
      const r = await fetch('/api/session/' + encodeURIComponent(id), { method:'GET' });
      if (!r.ok) throw new Error('A beszélgetés betöltése sikertelen');
      const data = await r.json();
      sid = id;
      msgs = [];
      ml.innerHTML = '';
      const deleted = new Set((deletedGroups[sid] || []).map(x => normalizeWhitespace(x)));

      const items = Array.isArray(data.messages) ? data.messages : [];
      for (const m of items) {
        if (!m || typeof m !== 'object') continue;
        if (m.role === 'user') {
          const rawText = String(m.rawText ?? m.content ?? '');
          const textAttsValue = Array.isArray(m.textAtts) ? m.textAtts : [];
          const imgUrls = Array.isArray(m.imageUrls) ? m.imageUrls : [];
          const display = buildUserDisplayText(rawText, textAttsValue);
          const key = normalizeWhitespace(display);
          if (deleted.has(key)) continue;
          msgs.push({
            role:'user',
            content:display,
            rawText,
            imageUrls:imgUrls.slice(),
            textAtts:textAttsValue.map(a => ({ ...a })),
            ts:Number(m.ts || Date.now())
          });
          ml.appendChild(mkUserGroup(rawText, imgUrls, textAttsValue, Number(m.ts || Date.now())));
        } else {
          const content = String(m.content ?? '');
          const key = normalizeWhitespace(content);
          if (deleted.has(key)) continue;
          msgs.push({
            role:'assistant',
            content,
            ts:Number(m.ts || Date.now())
          });
          ml.appendChild(mkAssistantGroup(md(content), content, Number(m.ts || Date.now())));
        }
      }
      renderHist();
      goBot();
    } catch (e) {
      toast(e.message || 'A beszélgetés betöltése sikertelen','err');
    }
  }

