  function processSSEEvent(block, ctx){
    const dataLines = String(block || '').split('\n').filter(line => line.startsWith('data:'));
    if (!dataLines.length) return;
    const raw = dataLines.map(line => line.slice(5).trimStart()).join('\n');
    if (!raw) return;

    let ev;
    try {
      ev = JSON.parse(raw);
    } catch (_) {
      return;
    }

    if (ev.type === 'token' || ev.type === 'delta') {
      const chunk = String(ev.text ?? ev.delta ?? '');
      if (!chunk) return;
      ctx.acc += chunk;
      ctx.render();
      return;
    }

    if (ev.type === 'done') {
      ctx.done = true;
      return;
    }

    if (ev.type === 'error') {
      throw new Error(String(ev.message || 'Hiba történt'));
    }
  }

  async function streamReq(apiUrl, payload, ctxState, retries = 1){
    const abortController = new AbortController();
    ctrl = abortController;
    const timeoutId = window.setTimeout(() => {
      try { abortController.abort(); } catch (_) {}
    }, 90000);

    try {
      const resp = await fetch(apiUrl, {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify(payload),
        signal: abortController.signal
      });

      if (!resp.ok) {
        const error = new Error('HTTP ' + resp.status);
        error.httpStatus = resp.status;
        throw error;
      }

      if (resp.status === 204 || !resp.body) {
        clearTimeout(timeoutId);
        return;
      }

      const reader = resp.body.getReader();
      const dec = new TextDecoder();
      let buf = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buf += dec.decode(value, { stream:true });

        let idx;
        while ((idx = buf.indexOf('\n\n')) !== -1) {
          const block = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          processSSEEvent(block, ctxState);
        }
      }

      buf += dec.decode();
      if (buf.trim()) {
        processSSEEvent(buf, ctxState);
      }
      clearTimeout(timeoutId);
    } catch (e) {
      clearTimeout(timeoutId);
      if (e && e.name === 'AbortError') {
        if (streaming) {
          toast('A kérés megszakadt','err');
        }
        throw e;
      }
      const status = Number(e && (e.httpStatus || e._httpStatus) || 0);
      const noRetry = status === 401 || status === 403 || status === 404;
      if (!noRetry && retries < 3) {
        appendReconnectBar('Újracsatlakozás…');
        const delay = 1400 * Math.pow(2, retries - 1) + Math.round(Math.random() * 350);
        await new Promise(resolve => {
          retryT = window.setTimeout(resolve, delay);
        });
        retryT = null;
        rmRcn();
        return await streamReq(apiUrl, payload, ctxState, retries + 1);
      }
      throw e;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  async function retryFromPayload(payload){
    if (streaming) {
      toast('Várd meg, amíg a jelenlegi válasz befejeződik','inf');
      return;
    }
    await populateComposerFromPayload(payload);
    await send();
  }

  async function send(){
    if (streaming) {
      stop();
      return;
    }

    const text = ta.value.trim();
    if (!text && !imgs.length && !textAtts.length) return;

    const originalText = ta.value;
    const currentImages = imgs.slice();
    const currentTextAtts = cloneTextAttachments(textAtts);

    ta.value = '';
    clearComposerAttachments();
    grow();

    const userGroup = mkUserGroup(text, currentImages, currentTextAtts, Date.now());
    ml.appendChild(userGroup);

    const userMsg = {
      role:'user',
      content: buildUserDisplayText(text, currentTextAtts),
      rawText:text,
      imageUrls: currentImages.slice(),
      textAtts: currentTextAtts,
      ts: Date.now(),
      agentMode
    };
    msgs.push(userMsg);
    updHist();
    goBot(true);

    const typing = mkTyping();
    ml.appendChild(typing);
    goBot(true);

    setStream(true);

    try {
      const realSid = await createSessionIfNeeded();
      const imgPay = currentImages.map(dataUrlToImgPayload).filter(Boolean);
      const payload = {
        sid: realSid,
        message: text,
        images: imgPay,
        textAtts: currentTextAtts,
        agentMode
      };

      const state = {
        acc:'',
        done:false,
        render(){
          if (!typing.isConnected) return;
          const html = md(this.acc);
          const plain = extractPlainTextFromHtml(html);
          const replacement = mkAssistantGroup(html, plain, Date.now());
          typing.replaceWith(replacement);
          this.node = replacement;
          if (window.hljs && typeof window.hljs.highlightElement === 'function') {
            replacement.querySelectorAll('pre code').forEach(code => {
              try { window.hljs.highlightElement(code); } catch (_) {}
            });
          }
          replacement.querySelectorAll('[data-copy-code]').forEach(btn => {
            btn.onclick = async () => {
              const code = btn.closest('.cb')?.querySelector('code')?.textContent || '';
              await cptext(code);
            };
          });
          goBot(true);
        }
      };

      await streamReq('/api/chat', payload, state);

      if (typing.isConnected) {
        const html = md(state.acc);
        const plain = extractPlainTextFromHtml(html);
        const finalGroup = mkAssistantGroup(html, plain, Date.now());
        typing.replaceWith(finalGroup);
        if (window.hljs && typeof window.hljs.highlightElement === 'function') {
          finalGroup.querySelectorAll('pre code').forEach(code => {
            try { window.hljs.highlightElement(code); } catch (_) {}
          });
        }
        finalGroup.querySelectorAll('[data-copy-code]').forEach(btn => {
          btn.onclick = async () => {
            const code = btn.closest('.cb')?.querySelector('code')?.textContent || '';
            await cptext(code);
          };
        });
      }

      msgs.push({
        role:'assistant',
        content: state.acc,
        ts: Date.now()
      });

      updHist();
      goBot(true);
    } catch (e) {
      if (typing.isConnected) typing.remove();
      ml.appendChild(mkError(e && e.name === 'AbortError' ? 'A kérés megszakadt.' : (e.message || 'Hiba történt.')));
      msgs.push({
        role:'assistant',
        content: e && e.name === 'AbortError' ? 'A kérés megszakadt.' : (e.message || 'Hiba történt.'),
        ts: Date.now()
      });
      if (!msgs.some(m => m.role === 'assistant')) {
        ta.value = originalText;
        grow();
      }
      updHist();
      goBot(true);
    } finally {
      ctrl = null;
      setStream(false);
    }
  }

  async function init(){
    try {
      const rawH = localStorage.getItem(HK);
      const rawD = localStorage.getItem(DK);
      hmeta = rawH ? JSON.parse(rawH) : [];
      deletedGroups = rawD ? JSON.parse(rawD) : {};
    } catch (_) {
      hmeta = [];
      deletedGroups = {};
    }

    hmeta = Array.isArray(hmeta) ? hmeta.filter(item => item && typeof item === 'object' && item.sid) : [];
    deletedGroups = deletedGroups && typeof deletedGroups === 'object' ? deletedGroups : {};

    try {
      const r = await fetch('/api/sessions', { method:'GET' });
      if (r.ok) {
        const data = await r.json();
        const list = Array.isArray(data.sessions) ? data.sessions : [];
        const merged = [];
        const seen = new Set();

        for (const s of list) {
          const item = {
            sid: String(s.sid || s.id || ''),
            preview: String(s.preview || 'Új chat'),
            ts: Number(new Date(s.updated_at || s.ts || Date.now()).getTime())
          };
          if (!item.sid || seen.has(item.sid)) continue;
          seen.add(item.sid);
          merged.push(item);
        }

        for (const item of hmeta) {
          if (!item.sid || seen.has(item.sid)) continue;
          seen.add(item.sid);
          merged.push({
            sid:String(item.sid),
            preview:String(item.preview || 'Új chat'),
            ts:Number(item.ts || Date.now())
          });
        }

        hmeta = merged.sort((a,b) => Number(b.ts || 0) - Number(a.ts || 0));
        persist();

        const knownSids = new Set(hmeta.map(h => h.sid));
        let dirty = false;
        for (const key of Object.keys(deletedGroups)) {
          if (!knownSids.has(key)) {
            delete deletedGroups[key];
            dirty = true;
          }
        }
        if (dirty) persistDeletedGroups();
      }
    } catch (_) {}

    sid = 'local-' + Date.now();
    renderHist();
    closeSB();
    setAgentMode(false);
    updateSendBtn();
    grow();
    setIBH();
  }

  el('btn-sidebar')?.addEventListener('click', () => {
    if (sbOpen) closeSB();
    else openSB();
  });
  el('sb-back')?.addEventListener('click', closeSB);
  el('sb-search-toggle')?.addEventListener('click', () => {
    if (sbSearchBar.classList.contains('open')) closeSearch();
    else openSearch();
  });
  el('new-chat')?.addEventListener('click', () => {
    newChat();
    closeSB();
  });
  el('btn-gal')?.addEventListener('click', () => fg.click());
  fg.addEventListener('change', async e => {
    await handleFiles(e.target.files);
    e.target.value = '';
  });
  ta.addEventListener('input', () => {
    grow();
    updateSendBtn();
  });
  ta.addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      void send();
    }
  });
  ta.addEventListener('paste', async e => {
    const items = Array.from(e.clipboardData?.items || []);
    const imgItems = items.filter(item => String(item.type || '').startsWith('image/'));
    if (!imgItems.length) return;
    e.preventDefault();
    const pastedText = e.clipboardData?.getData('text/plain') || '';
    if (pastedText) {
      const start = ta.selectionStart;
      const end = ta.selectionEnd;
      const before = ta.value.slice(0,start);
      const after = ta.value.slice(end);
      ta.value = before + pastedText + after;
      const next = before.length + pastedText.length;
      ta.selectionStart = ta.selectionEnd = next;
    }
    for (const item of imgItems) {
      const file = item.getAsFile();
      if (file) {
        await handleFiles([file]);
      }
    }
    grow();
    updateSendBtn();
  });
  sbtn.addEventListener('click', () => {
    void send();
  });
  stb.addEventListener('click', () => goBot(true));
  sbQ.addEventListener('input', renderHist);
  el('sb-q-cancel')?.addEventListener('click', closeSearch);

  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'f') {
      e.preventDefault();
      openSB();
      openSearch();
    }
    if (e.key === 'Escape' && sbOpen) {
      closeSB();
    }
  });

  let scrollTimer = null;
  sa.addEventListener('scroll', () => {
    sa.classList.add('scrolling');
    if (scrollTimer) clearTimeout(scrollTimer);
    scrollTimer = window.setTimeout(() => sa.classList.remove('scrolling'), 140);
    if (nearBot()) stb.classList.remove('show');
    else stb.classList.add('show');
  }, { passive:true });

  if (window.visualViewport) {
    const syncVV = () => setIBH();
    window.visualViewport.addEventListener('resize', syncVV);
    document.addEventListener('focusout', () => {
      window.setTimeout(syncVV, 80);
    }, { passive:true });
  }

  const ibWrap = el('ib-wrap');
  if (ibWrap && 'ResizeObserver' in window) {
    new ResizeObserver(() => {
      setIBH();
      if (nearBot()) goBot();
    }).observe(ibWrap);
  }

  let tsX = 0;
  let tsY = 0;
  let sbDragging = false;
  const SB_EDGE_ZONE = 36;
  const tapThreshold = 18;

  document.addEventListener('touchstart', e => {
    if (!e.touches || !e.touches.length) return;
    const t = e.touches[0];
    tsX = t.clientX;
    tsY = t.clientY;
    if (!sbOpen && tsX < SB_EDGE_ZONE) {
      sbDragging = true;
      sidebar.classList.add('dragging');
    }
  }, { passive:true });

  document.addEventListener('touchmove', e => {
    if (!sbDragging || !e.touches || !e.touches.length) return;
    const t = e.touches[0];
    const dx = Math.max(0, t.clientX - tsX);
    const pct = Math.min(1, dx / (window.innerWidth * 0.8));
    sidebar.style.transform = 'translateX(' + (-100 + pct * 100) + '%)';
  }, { passive:true });

  document.addEventListener('touchend', e => {
    const changed = e.changedTouches && e.changedTouches[0];
    const endX = changed ? changed.clientX : tsX;
    const dx = endX - tsX;

    if (sbDragging) {
      sidebar.classList.remove('dragging');
      sidebar.style.transform = '';
      if (dx > window.innerWidth * 0.18) openSB();
      else closeSB();
      sbDragging = false;
      return;
    }

    if (!sbOpen && tsX < SB_EDGE_ZONE && dx > tapThreshold) {
      openSB();
    }
  }, { passive:true });

  init();

  const ctxOverlay = el('ctx-overlay');
  const ctxPreview = el('ctx-preview');
  const ctxMenu = el('ctx-menu');
  let ctxGroup = null;
  let longPressTimer = null;
  let lpStartX = 0;
  let lpStartY = 0;

  function closeCtx(){
    ctxOverlay.classList.remove('vis');
    ctxPreview.classList.remove('vis');
    ctxMenu.classList.remove('vis');
    window.setTimeout(() => {
      ctxPreview.innerHTML = '';
      ctxMenu.innerHTML = '';
      ctxGroup = null;
    }, 170);
  }

  function findMsgGroup(target){
    if (!(target instanceof Element)) return null;
    return target.closest('.msg-group');
  }

  function buildPreview(group){
    const role = group?.dataset?.role || '';
    const preview = document.createElement('div');
    preview.className = 'ai-bubble';
    if (role === 'user') {
      preview.className = 'bubble';
      preview.textContent = safeSliceText(getGroupCopyText(group), 280);
    } else {
      preview.className = 'ai-bubble';
      const mdEl = document.createElement('div');
      mdEl.className = 'md';
      mdEl.textContent = safeSliceText(getGroupCopyText(group), 280);
      preview.appendChild(mdEl);
    }
    return preview;
  }

  function showCtx(group, x, y){
    if (!group) return;
    ctxGroup = group;
    ctxPreview.innerHTML = '';
    ctxPreview.appendChild(buildPreview(group));

    const items = [
      {
        key:'copy',
        label:'Másolás',
        icon:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M16 1H4a2 2 0 0 0-2 2v12h2V3h12zm3 4H8a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2zm0 16H8V7h11z\"/></svg>'
      }
    ];

    if (group.dataset.role === 'user') {
      items.push({
        key:'edit',
        label:'Szerkesztés',
        icon:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 17.25V21h3.75L17.81 9.94l-3.75-3.75zM20.71 7.04a1.003 1.003 0 0 0 0-1.42l-2.34-2.34a1.003 1.003 0 0 0-1.42 0L15.13 5.1l3.75 3.75z\"/></svg>'
      });
      items.push({
        key:'resend',
        label:'Újraküldés',
        icon:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 6V3L8 7l4 4V8c2.76 0 5 2.24 5 5a5 5 0 0 1-8.66 3.54l-1.42 1.42A7 7 0 1 0 19 13c0-3.87-3.13-7-7-7z\"/></svg>'
      });
    }

    items.push({
      key:'delete',
      label:'Törlés',
      icon:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M6 7h12l-1 14H7L6 7zm3-4h6l1 2h4v2H4V5h4l1-2z\"/></svg>',
      danger:true
    });

    ctxMenu.innerHTML = '';
    items.forEach(item => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'ctx-item' + (item.danger ? ' danger' : '');
      btn.dataset.action = item.key;
      btn.innerHTML = item.icon + '<span>' + escHtml(item.label) + '</span>';
      ctxMenu.appendChild(btn);
    });

    ctxOverlay.classList.add('vis');
    ctxPreview.classList.add('vis');
    ctxMenu.classList.add('vis');

    requestAnimationFrame(() => {
      const pr = ctxPreview.getBoundingClientRect();
      const mr = ctxMenu.getBoundingClientRect();
      const pad = 12;
      const px = Math.min(Math.max(pad, x - pr.width / 2), window.innerWidth - pr.width - pad);
      const py = Math.min(Math.max(pad, y - pr.height - mr.height - 16), window.innerHeight - pr.height - mr.height - 24);
      ctxPreview.style.left = px + 'px';
      ctxPreview.style.top = py + 'px';
      const mx = Math.min(Math.max(pad, x - mr.width / 2), window.innerWidth - mr.width - pad);
      const my = Math.min(window.innerHeight - mr.height - pad, py + pr.height + 8);
      ctxMenu.style.left = mx + 'px';
      ctxMenu.style.top = my + 'px';
    });
  }

  async function handleCtxAction(action){
    if (!ctxGroup) return;
    if (action === 'copy') {
      await cptext(getGroupCopyText(ctxGroup));
      closeCtx();
      return;
    }

    if (action === 'edit') {
      const payload = getUserComposerPayload(ctxGroup);
      if (payload) {
        await populateComposerFromPayload(payload);
        ta.focus();
      }
      closeCtx();
      return;
    }

    if (action === 'resend') {
      const payload = getUserComposerPayload(ctxGroup);
      closeCtx();
      if (payload) {
        await retryFromPayload(payload);
      }
      return;
    }

    if (action === 'delete') {
      const text = getGroupCoreText(ctxGroup);
      const idx = Array.from(ml.children).indexOf(ctxGroup);
      if (idx >= 0) {
        msgs.splice(idx,1);
      }
      markDeletedGroup(sid, text);
      ctxGroup.style.transition = 'opacity .22s, transform .26s cubic-bezier(.2,1,.3,1)';
      ctxGroup.style.opacity = '0';
      ctxGroup.style.transform = 'translateY(8px) scale(.98)';
      const target = ctxGroup;
      closeCtx();
      let doneCalled = false;
      const done = () => {
        if (doneCalled) return;
        doneCalled = true;
        if (target.isConnected) target.remove();
        syncMsgsFromDom();
        updHist();
        renderHist();
      };
      target.addEventListener('transitionend', done, { once:true });
      window.setTimeout(done, 340);
    }
  }

  ctxOverlay.addEventListener('click', closeCtx);
  ctxMenu.addEventListener('click', e => {
    const btn = e.target.closest('.ctx-item');
    if (!btn) return;
    void handleCtxAction(btn.dataset.action);
  });

  ml.addEventListener('contextmenu', e => {
    const group = findMsgGroup(e.target);
    if (!group) return;
    e.preventDefault();
    showCtx(group, e.clientX, e.clientY);
  });

  ml.addEventListener('touchstart', e => {
    const group = findMsgGroup(e.target);
    if (!group || !e.touches || !e.touches.length) return;
    const t = e.touches[0];
    lpStartX = t.clientX;
    lpStartY = t.clientY;
    if (longPressTimer) clearTimeout(longPressTimer);
    longPressTimer = window.setTimeout(() => {
      longPressTimer = null;
      if (group.isConnected) {
        if (navigator.vibrate) navigator.vibrate([12]);
        showCtx(group, lpStartX, lpStartY);
      }
    }, 500);
  }, { passive:true });

  ml.addEventListener('touchmove', e => {
    if (!longPressTimer || !e.touches || !e.touches.length) return;
    const t = e.touches[0];
    if (Math.abs(t.clientX - lpStartX) > 10 || Math.abs(t.clientY - lpStartY) > 10) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  }, { passive:true });

  ml.addEventListener('touchend', () => {
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  }, { passive:true });

})();
</script>
</body>
</html>
